impl fmt::Display for BlockSymbol {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        use BlockSymbol::*;
        let s0 = match *self {
            Run(t, _) => &format!("{:?}", t),
            _ => &format!("{:?}", self),
        };
        let s_exp = match *self {
            Run(_, n) => {
                if n == 1 {
                    ""
                } else {
                    &format!("^{}", n)
                }
            }
            _ => "",
        };
        write!(f, "{}{}", s0, s_exp)
    }
}

